package com.bn.aliagent.insight.radar; import java.math.*; import java.util.*;
public final class AnomalyDetector { public AnomalyResult detect(ThresholdRule rule,BigDecimal current,long sample,List<BigDecimal> samePeriod){var baseline=TrendBaseline.from(samePeriod);if(sample<rule.minimumSampleSize())return new AnomalyResult(false,true,List.of(),baseline);var reasons=new ArrayList<String>();if(current.compareTo(rule.absoluteThreshold())>=0)reasons.add("ABSOLUTE_THRESHOLD");if(current.compareTo(baseline.sevenDay().multiply(rule.trendMultiplier()))>=0||current.compareTo(baseline.twentyEightDay().multiply(rule.trendMultiplier()))>=0)reasons.add("TREND_7_28");return new AnomalyResult(!reasons.isEmpty(),false,List.copyOf(reasons),baseline);}}
